local macro = {
    Name = "MyMacro",
    CreatedAt = os.time(),
    Actions = {}
}

-- Per-instance runtime information.
local towerRecords = {}

-- Persistent IDs used by the macro.
local macroTowerIds = {}

-- Runtime replay references.
local replayTowers = {}

-- Connections owned by the macro.
local connections = {}

local nextTowerId = 0

--========================================================
-- CONNECTION MANAGEMENT
--========================================================

local function addConnection(connection)
    table.insert(connections, connection)
    return connection
end

local function disconnectAll()

    for i = #connections, 1, -1 do

        local connection =
            connections[i]

        if connection then

            pcall(function()
                connection:Disconnect()
            end)

        end

        connections[i] = nil
    end
end

--========================================================
-- GUI
--========================================================
--
-- Remove any previous macro GUI left behind by an earlier
-- execution of this script in the same session, so you can
-- never be looking at a stale duplicate while the real one
-- updates underneath it.
--========================================================

do

    local parent =
        getUIParent()

    local old =
        parent:FindFirstChild(
            "TowerDefenseMacro"
        )

    while old do

        pcall(function()
            old:Destroy()
        end)

        old =
            parent:FindFirstChild(
                "TowerDefenseMacro"
            )
    end
end

