local function makeButton(text, x, y)

    local b = Instance.new("TextButton")

    b.Size =
        UDim2.fromOffset(160, 40)

    b.Position =
        UDim2.fromOffset(x, y)

    b.Text = text
    b.TextColor3 = Color3.new(1, 1, 1)
    b.TextSize = 13
    b.Font = Enum.Font.GothamBold

    b.BackgroundColor3 =
        Color3.fromRGB(48, 48, 48)

    b.BorderSizePixel = 0

    local c = Instance.new("UICorner")

    c.CornerRadius =
        UDim.new(0, 8)

    c.Parent = b
    b.Parent = main

    return b
end

