--========================================================
-- GAME STATE
--========================================================

local function getWave()

    local state =
        ReplicatedStorage:FindFirstChild("WaveState")

    if state then
        return state:GetAttribute("CurrentWave") or 0
    end

    return 0
end

local function getCash()

    local leaderstats =
        Player:FindFirstChild("leaderstats")

    if not leaderstats then
        return 0
    end

    local cash =
        leaderstats:FindFirstChild("Cash")

    if cash then
        return cash.Value
    end

    return 0
end

--========================================================
-- SAFE ATTRIBUTE READ
--========================================================

local function getAttribute(tower, names)

    for _, name in ipairs(names) do

        local value =
            tower:GetAttribute(name)

        if value ~= nil then
            return value
        end
    end

    return nil
end

--========================================================
-- TOWER HELPERS
--========================================================

local function getPersistentTowerId(tower)

    -- Prefer IDs that the game itself provides.

    local value =
        getAttribute(
            tower,
            {
                "TowerId",
                "UniqueId",
                "UniqueID",
                "UUID",
                "GUID",
                "Id",
                "ID",
                "InstanceId",
                "InstanceID"
            }
        )

    if value ~= nil then
        return tostring(value), "GameId"
    end

    -- Some games use a macro-specific/server attribute.

    value =
        getAttribute(
            tower,
            {
                "MacroTowerId",
                "MacroId"
            }
        )

    if value ~= nil then
        return tostring(value), "MacroId"
    end

    return nil, nil
end

local function getUnitId(tower)

    return
        getAttribute(
            tower,
            {
                "UnitId",
                "UnitID"
            }
        )
        or
        getAttribute(
            tower,
            {
                "ModelName"
            }
        )
        or
        tower.Name
end

local function getLevel(tower)

    local level =
        getAttribute(
            tower,
            {
                "Level",
                "TowerLevel",
                "Upgrade",
                "UpgradeLevel"
            }
        )

    if level ~= nil then
        return tonumber(level)
    end

    return nil
end

local function getOwner(tower)

    local ownerId =
        getAttribute(
            tower,
            {
                "OwnerUserId",
                "OwnerUserID"
            }
        )

    if ownerId ~= nil then
        return tonumber(ownerId) == Player.UserId
    end

    local owner =
        tower:GetAttribute("Owner")

    if owner ~= nil then

        if typeof(owner) == "Instance" then
            return owner == Player
        end

        return tostring(owner) == Player.Name
    end

    return true
end

local function getCFrame(tower)

    if tower:IsA("Model") then
        return tower:GetPivot()
    end

    if tower:IsA("BasePart") then
        return tower.CFrame
    end

    return CFrame.new()
end

--========================================================
-- COMPLETE CFRAME SERIALIZATION
--========================================================

local function serializeCFrame(cf)

    local components = {
        cf:GetComponents()
    }

    return {
        Components = components,

        Position = {
            cf.Position.X,
            cf.Position.Y,
            cf.Position.Z
        },

        LookVector = {
            cf.LookVector.X,
            cf.LookVector.Y,
            cf.LookVector.Z
        }
    }
end

local function deserializeCFrame(data)

    if type(data) ~= "table" then
        return nil
    end

    -- Preferred format: all 12 CFrame components.

    if type(data.Components) == "table"
        and #data.Components == 12 then

        local values = {}

        for i = 1, 12 do

            local n =
                tonumber(
                    data.Components[i]
                )

            if not n then
                return nil
            end

            values[i] = n
        end

        return CFrame.new(
            table.unpack(values)
        )
    end

    -- Backwards compatibility with the old format.

    local p = data.Position

    if type(p) ~= "table"
        or #p < 3 then

        return nil
    end

    local px = tonumber(p[1])
    local py = tonumber(p[2])
    local pz = tonumber(p[3])

    if not px or not py or not pz then
        return nil
    end

    local l = data.LookVector

    if type(l) == "table"
        and #l >= 3 then

        local lx = tonumber(l[1])
        local ly = tonumber(l[2])
        local lz = tonumber(l[3])

        if lx and ly and lz then

            local look =
                Vector3.new(
                    lx,
                    ly,
                    lz
                )

            if look.Magnitude > 0.001 then

                local position =
                    Vector3.new(
                        px,
                        py,
                        pz
                    )

                return CFrame.lookAt(
                    position,
                    position + look
                )
            end
        end
    end

    return CFrame.new(
        px,
        py,
        pz
    )
end

--========================================================
-- MACRO TOWER IDS
--========================================================

local function createMacroTowerId()

    nextTowerId += 1

    return
        "T" ..
        tostring(nextTowerId)
end

local function getMacroTowerId(tower)

    if macroTowerIds[tower] then
        return macroTowerIds[tower]
    end

    local persistentId =
        getPersistentTowerId(tower)

    if persistentId then

        macroTowerIds[tower] =
            "P:" .. persistentId

        return macroTowerIds[tower]
    end

    local id =
        createMacroTowerId()

    macroTowerIds[tower] = id

    -- Client-side marker.
    --
    -- If the game replaces the instance and copies this
    -- attribute, the replacement can retain the ID.

    pcall(function()

        tower:SetAttribute(
            "MacroTowerId",
            id
        )

    end)

    return id
end

--========================================================
-- ATTRIBUTE READINESS
--========================================================

local function towerAttributesReady(tower)

    if not tower
        or not tower.Parent then

        return false
    end

    if not getOwner(tower) then
        return false
    end

    local unitId =
        getUnitId(tower)

    if unitId == nil
        or tostring(unitId) == "" then

        return false
    end

    return true
end

local function waitForTowerReady(
    tower,
    timeout
)

    if not tower then
        return nil
    end

    local deadline =
        os.clock() + timeout

    while os.clock() < deadline do

        if not tower.Parent then
            return nil
        end

        if towerAttributesReady(tower) then
            return tower
        end

        RunService.Heartbeat:Wait()
    end

    return nil
end

--========================================================
-- TOWER SNAPSHOT
--========================================================

local function snapshotTowers()

    local result = {}

    for _, tower in ipairs(
        TowersFolder:GetChildren()
    ) do

        if getOwner(tower) then

            local ready =
                towerAttributesReady(tower)

            if ready then

                local id =
                    getMacroTowerId(tower)

                result[tower] = {

                    Id = id,

                    PersistentId =
                        select(
                            1,
                            getPersistentTowerId(
                                tower
                            )
                        ),

                    UnitId =
                        tostring(
                            getUnitId(tower)
                        ),

                    Name =
                        tower.Name,

                    Level =
                        getLevel(tower),

                    CFrame =
                        getCFrame(tower)
                }
            end
        end
    end

    return result
end

--========================================================
-- ACTION DUPLICATE PROTECTION
--========================================================

local function actionEquivalent(a, b)

    if not a or not b then
        return false
    end

    if a.Type ~= b.Type then
        return false
    end

    if a.TowerId ~= b.TowerId then
        return false
    end

    if a.Type == "UpgradeTower" then

        return
            a.LevelBefore == b.LevelBefore
            and
            a.LevelAfter == b.LevelAfter

    elseif a.Type == "PlaceTower" then

        return
            a.UnitId == b.UnitId
            and
            a.CFrame ~= nil
            and
            b.CFrame ~= nil

    elseif a.Type == "SellTower" then

        return true
    end

    return false
end

--========================================================
-- ADD ACTION
--========================================================

local function addAction(action)

    if not recording then
        return false
    end

    local last =
        macro.Actions[
            #macro.Actions
        ]

    if actionEquivalent(
        action,
        last
    ) then

        return false
    end

    action.Time =
        math.max(
            0,
            math.floor(
                (
                    os.clock()
                    - recordStart
                ) * 1000
            ) / 1000
        )

    action.Wave = getWave()
    action.CashBefore = getCash()

    table.insert(
        macro.Actions,
        action
    )

    print(
        "[MACRO]",
        action.Type,
        action.TowerId or "",
        action.UnitId or ""
    )

    return true
end

--========================================================
-- POSITION FALLBACK
--========================================================

local function lastResortPositionMatch(
    action,
    excluded
)

    warn(
        "[MACRO] LAST-RESORT POSITION MATCH:",
        action.TowerId or "unknown"
    )

    local cf =
        deserializeCFrame(
            action.CFrame
        )

    if not cf then
        return nil
    end

    local wantedPosition =
        cf.Position

    local best = nil
    local bestDistance = math.huge

    for _, tower in ipairs(
        TowersFolder:GetChildren()
    ) do

        if tower ~= excluded
            and towerAttributesReady(tower) then

            local sameUnit =
                tostring(
                    getUnitId(tower)
                )
                ==
                tostring(
                    action.UnitId
                )

            if sameUnit then

                local distance =
                    (
                        getCFrame(tower).Position
                        -
                        wantedPosition
                    ).Magnitude

                if distance < bestDistance then

                    bestDistance =
                        distance

                    best = tower
                end
            end
        end
    end

    return best
end

--========================================================
-- FIND TOWER BY UNIQUE ID
--========================================================

local function findTowerById(
    towerId
)

    if not towerId then
        return nil
    end

    -- First use replay cache.

    local cached =
        replayTowers[towerId]

    if cached
        and cached.Parent then

        return cached
    end

    -- Search game-provided persistent IDs.

    for _, tower in ipairs(
        TowersFolder:GetChildren()
    ) do

        if towerAttributesReady(tower) then

            local persistentId =
                getPersistentTowerId(
                    tower
                )

            if persistentId
                and (
                    "P:" .. persistentId
                )
                == towerId then

                replayTowers[towerId] =
                    tower

                return tower
            end

            local macroId =
                tower:GetAttribute(
                    "MacroTowerId"
                )

            if macroId
                and tostring(macroId)
                    == tostring(towerId) then

                replayTowers[towerId] =
                    tower

                return tower
            end
        end
    end

    return nil
end

--========================================================
-- FIND TOWER FOR ACTION
--========================================================

local function findTowerForAction(
    action,
    allowFallback
)

    local tower =
        findTowerById(
            action.TowerId
        )

    if tower then
        return tower, "UniqueId"
    end

    if not allowFallback then
        return nil, "NotFound"
    end

    -- This is deliberately NOT the normal path.

    tower =
        lastResortPositionMatch(
            action
        )

    if tower then

        replayTowers[
            action.TowerId
        ] = tower

        return tower, "PositionFallback"
    end

    return nil, "NotFound"
end

--========================================================
-- DETECT REPLACEMENT
--========================================================

local function findReplacementByPersistentId(
    oldTower,
    action,
    deadline
)

    local oldPersistentId =
        getPersistentTowerId(
            oldTower
        )

    while os.clock() < deadline do

        for _, candidate in ipairs(
            TowersFolder:GetChildren()
        ) do

            if candidate ~= oldTower
                and candidate.Parent
                and towerAttributesReady(candidate) then

                local candidateId =
                    getPersistentTowerId(
                        candidate
                    )

                if oldPersistentId
                    and candidateId
                    and candidateId
                        == oldPersistentId then

                    return candidate
                end

                local macroId =
                    candidate:GetAttribute(
                        "MacroTowerId"
                    )

                if macroId
                    and action.TowerId
                    and tostring(macroId)
                        == tostring(
                            action.TowerId
                        ) then

                    return candidate
                end
            end
        end

        RunService.Heartbeat:Wait()
    end

    return nil
end

local function waitForUpgradeReplacement(
    oldTower,
    action,
    timeout
)

    local deadline =
        os.clock() + timeout

    --====================================================
    -- 1. Wait for the existing tower to actually change.
    --====================================================

    while os.clock() < deadline do

        if oldTower
            and oldTower.Parent then

            local currentLevel =
                getLevel(oldTower)

            if action.LevelAfter
                and currentLevel
                and tonumber(currentLevel)
                    >= tonumber(
                        action.LevelAfter
                    ) then

                return oldTower,
                    "SameInstance"
            end
        end

        RunService.Heartbeat:Wait()
    end

    --====================================================
    -- 2. If the old tower was replaced, search by ID.
    --====================================================

    local replacement =
        findReplacementByPersistentId(
            oldTower,
            action,
            deadline
        )

    if replacement then

        return replacement,
            "UniqueIdReplacement"
    end

    --====================================================
    -- 3. Explicit last-resort fallback.
    --====================================================

    warn(
        "[MACRO] Upgrade replacement has no recoverable",
        "persistent ID. Using LAST-RESORT position matching."
    )

    local fallback =
        lastResortPositionMatch(
            action,
            oldTower
        )

    if fallback then
        return fallback,
            "PositionFallback"
    end

    return nil, "Desync"
end

--========================================================
-- RECORD CHANGE PROCESSING
--========================================================

local function processChanges()

    if not recording then
        return
    end

    local current =
        snapshotTowers()

    --====================================================
    -- New towers and level changes.
    --====================================================

    for tower, data in pairs(current) do

        local old =
            towerRecords[tower]

        if not old then

            -- If this is a replacement and the instance
            -- carries the previous macro ID, preserve it.

            local inheritedId =
                tower:GetAttribute(
                    "MacroTowerId"
                )

            if inheritedId then

                macroTowerIds[tower] =
                    tostring(inheritedId)

                data.Id =
                    tostring(inheritedId)
            end

            addAction({

                Type = "PlaceTower",

                TowerId = data.Id,

                PersistentId =
                    data.PersistentId,

                UnitId = data.UnitId,

                Tower = data.Name,

                Level = data.Level,

                CFrame =
                    serializeCFrame(
                        data.CFrame
                    )
            })

        else

            --================================================
            -- Upgrade detection.
            --
            -- Level must be known on BOTH sides.
            -- This prevents "nil -> 1" from becoming
            -- a fake upgrade.
            --================================================

            if old.Level ~= nil
                and data.Level ~= nil
                and tonumber(old.Level)
                    ~= tonumber(data.Level) then

                if tonumber(data.Level)
                    > tonumber(old.Level) then

                    addAction({

                        Type =
                            "UpgradeTower",

                        TowerId =
                            data.Id,

                        PersistentId =
                            data.PersistentId
                            or old.PersistentId,

                        UnitId =
                            data.UnitId,

                        Tower =
                            data.Name,

                        LevelBefore =
                            old.Level,

                        LevelAfter =
                            data.Level,

                        CFrame =
                            serializeCFrame(
                                data.CFrame
                            )
                    })
                end
            end

            --================================================
            -- Movement / rotation detection.
            --
            -- Only record this if the CFrame actually changed.
            --================================================

            if old.CFrame
                and data.CFrame then

                local oldComponents = {
                    old.CFrame:GetComponents()
                }

                local newComponents = {
                    data.CFrame:GetComponents()
                }

                local changed = false

                for i = 1, 12 do

                    if math.abs(
                        oldComponents[i]
                        -
                        newComponents[i]
                    ) > 0.0001 then

                        changed = true
                        break
                    end
                end

                if changed
                    and old.Level
                    and data.Level
                    and tonumber(old.Level)
                        == tonumber(data.Level) then

                    -- Optional movement recording.
                    --
                    -- The action is separate so that replay
                    -- can recognize it without confusing it
                    -- with placement or upgrading.

                    addAction({

                        Type =
                            "MoveTower",

                        TowerId =
                            data.Id,

                        PersistentId =
                            data.PersistentId
                            or old.PersistentId,

                        UnitId =
                            data.UnitId,

                        Tower =
                            data.Name,

                        Level =
                            data.Level,

                        CFrame =
                            serializeCFrame(
                                data.CFrame
                            )
                    })
                end
            end
        end
    end

    --====================================================
    -- Removed towers.
    --====================================================

    for tower, old in pairs(
        towerRecords
    ) do

        if not current[tower] then

            -- If the tower was replaced during an upgrade,
            -- try to identify the replacement BEFORE calling
            -- this a sale.
            --
            -- A replacement normally has the same persistent
            -- ID or a copied MacroTowerId.

            local replacement = nil

            if old.PersistentId then

                for candidate, candidateData in pairs(
                    current
                ) do

                    if candidateData.PersistentId
                        and candidateData.PersistentId
                            == old.PersistentId then

                        replacement =
                            candidate

                        break
                    end
                end
            end

            if replacement then

                -- Replacement is handled by the new tower's
                -- state rather than being recorded as a sale.

                macroTowerIds[replacement] =
                    old.Id

            else

                addAction({

                    Type =
                        "SellTower",

                    TowerId =
                        old.Id,

                    PersistentId =
                        old.PersistentId,

                    UnitId =
                        old.UnitId,

                    Tower =
                        old.Name,

                    Level =
                        old.Level,

                    CFrame =
                        serializeCFrame(
                            old.CFrame
                        )
                })

                macroTowerIds[tower] =
                    nil
            end
        end
    end

    towerRecords =
        current
end

--========================================================
-- REPLAY: PLACE
--========================================================

local function replayPlace(
    action,
    token
)

    if token ~= playbackToken
        or not playing then

        return nil, "Cancelled"
    end

    local cf =
        deserializeCFrame(
            action.CFrame
        )

    if not cf then

        warn(
            "[MACRO] Invalid placement CFrame:",
            action.TowerId
        )

        return nil, "InvalidCFrame"
    end

    local ok, allowed =
        pcall(function()

            return CanPlaceTower:InvokeServer(
                action.UnitId
            )

        end)

    if not ok then

        warn(
            "[MACRO] CanPlaceTower failed:",
            allowed
        )

        return nil, "RemoteError"
    end

    if allowed ~= true then

        warn(
            "[MACRO] Placement rejected:",
            action.UnitId
        )

        return nil, "Rejected"
    end

    local success, result =
        pcall(function()

            return PlaceTower:InvokeServer(
                action.UnitId,
                cf
            )

        end)

    if not success then

        warn(
            "[MACRO] PlaceTower failed:",
            result
        )

        return nil, "RemoteError"
    end

    if token ~= playbackToken
        or not playing then

        return nil, "Cancelled"
    end

    -- Some games return the actual Instance.

    if typeof(result) == "Instance"
        and result.Parent then

        replayTowers[
            action.TowerId
        ] = result

        return result, "RemoteResult"
    end

    -- Otherwise wait for the actual tower event/state.

    local deadline =
        os.clock() + 5

    while os.clock() < deadline do

        if token ~= playbackToken
            or not playing then

            return nil, "Cancelled"
        end

        local tower =
            findTowerById(
                action.TowerId
            )

        if tower then

            return tower, "UniqueId"
        end

        -- A placement may not have a persistent game ID.
        -- Only after unique lookup fails do we use the
        -- explicitly reported fallback.

        for _, candidate in ipairs(
            TowersFolder:GetChildren()
        ) do

            if towerAttributesReady(candidate)
                and tostring(
                    getUnitId(candidate)
                )
                ==
                tostring(
                    action.UnitId
                ) then

                local candidateCF =
                    getCFrame(candidate)

                if (
                    candidateCF.Position
                    -
                    cf.Position
                ).Magnitude
                    < 0.5 then

                    warn(
                        "[MACRO] Placement used LAST-RESORT",
                        "position matching:",
                        action.TowerId
                    )

                    replayTowers[
                        action.TowerId
                    ] = candidate

                    return candidate,
                        "PositionFallback"
                end
            end
        end

        RunService.Heartbeat:Wait()
    end

    warn(
        "[MACRO] Placement desync:",
        action.TowerId
    )

    return nil, "Desync"
end

--========================================================
-- REPLAY: UPGRADE
--========================================================

local function replayUpgrade(
    action,
    token
)

    if token ~= playbackToken
        or not playing then

        return false, "Cancelled"
    end

    local tower, method =
        findTowerForAction(
            action,
            true
        )

    if not tower then

        warn(
            "[MACRO] Upgrade target not found:",
            action.TowerId
        )

        return false, "Desync"
    end

    -- Verify that we have not accidentally selected a
    -- completely unrelated tower.

    if action.UnitId
        and tostring(
            getUnitId(tower)
        )
        ~=
        tostring(
            action.UnitId
        ) then

        warn(
            "[MACRO] Upgrade target identity mismatch:",
            action.TowerId,
            method
        )

        return false, "IdentityMismatch"
    end

    local success, result =
        pcall(function()

            return UpgradeTower:InvokeServer(
                tower
            )

        end)

    if not success then

        warn(
            "[MACRO] UpgradeTower failed:",
            result
        )

        return false, "RemoteError"
    end

    if token ~= playbackToken
        or not playing then

        return false, "Cancelled"
    end

    --====================================================
    -- Critical fix:
    --
    -- Do not sleep an arbitrary 0.15 seconds.
    -- Wait for the actual level change or replacement.
    --====================================================

    local upgradedTower, replacementMethod =
        waitForUpgradeReplacement(
            tower,
            action,
            5
        )

    if not upgradedTower then

        warn(
            "[MACRO] DESYNC:",
            action.TowerId,
            "upgrade did not produce the expected tower."
        )

        return false, "Desync"
    end

    if token ~= playbackToken
        or not playing then

        return false, "Cancelled"
    end

    replayTowers[
        action.TowerId
    ] = upgradedTower

    -- Give the new instance a client-side macro marker.
    pcall(function()

        upgradedTower:SetAttribute(
            "MacroTowerId",
            action.TowerId
        )

    end)

    print(
        "[MACRO] Upgrade synchronized:",
        action.TowerId,
        replacementMethod
    )

    return true, replacementMethod
end

--========================================================
-- REPLAY: SELL
--========================================================

local function replaySell(
    action,
    token
)

    if token ~= playbackToken
        or not playing then

        return false, "Cancelled"
    end

    local tower, method =
        findTowerForAction(
            action,
            true
        )

    if not tower then

        warn(
            "[MACRO] Sell target not found:",
            action.TowerId
        )

        return false, "Desync"
    end

    local success, result =
        pcall(function()

            return SellTower:InvokeServer(
                tower
            )

        end)

    if not success then

        warn(
            "[MACRO] SellTower failed:",
            result
        )

        return false, "RemoteError"
    end

    replayTowers[
        action.TowerId
    ] = nil

    return true, method
end

--========================================================
-- REPLAY: MOVE
--========================================================

local function replayMove(
    action,
    token
)

    if token ~= playbackToken
        or not playing then

        return false, "Cancelled"
    end

    local tower =
        findTowerForAction(
            action,
            true
        )

    if not tower then

        warn(
            "[MACRO] Move target not found:",
            action.TowerId
        )

        return false, "Desync"
    end

    local cf =
        deserializeCFrame(
            action.CFrame
        )

    if not cf then

        return false, "InvalidCFrame"
    end

    -- There is no MoveTower RemoteFunction in the supplied
    -- API. If the game exposes one later, it can be integrated
    -- here. For now, preserve the action in the macro and
    -- report that replay cannot apply it through the known
    -- RemoteFunctions.

    warn(
        "[MACRO] MoveTower recorded but no MoveTower",
        "RemoteFunction exists in the supplied API:",
        action.TowerId
    )

    return false, "Unsupported"
end

--========================================================
-- REPLAY TIMING
--========================================================

local function preciseWait(
    duration,
    token
)

    if duration <= 0 then
        return true
    end

    local deadline =
        os.clock() + duration

    while true do

        if token ~= playbackToken
            or not playing then

            return false
        end

        local remaining =
            deadline - os.clock()

        if remaining <= 0 then
            return true
        end

        -- Let the scheduler sleep for almost all of the
        -- interval, then use Heartbeat for the final portion.
        --
        -- This avoids the old fixed 0.1/0.15 polling delays.

        if remaining > 0.02 then

            task.wait(
                math.max(
                    0,
                    remaining - 0.01
                )
            )

        else

            RunService.Heartbeat:Wait()
        end
    end
end

--========================================================
-- PLAY MACRO
--========================================================

local function playMacro()

    if playing then
        return
    end

    if recording then

        status.Text =
            "STOP RECORDING FIRST"

        return
    end

    if #macro.Actions == 0 then

        status.Text =
            "NO ACTIONS"

        return
    end

    playing = true

    playbackToken += 1

    local token =
        playbackToken

    replayTowers = {}

    status.TextColor3 =
        Color3.new(1, 1, 1)

    status.Text =
        "PLAYING"

    task.spawn(function()

        local previousTime = 0

        for index, action in ipairs(
            macro.Actions
        ) do

            if token ~= playbackToken
                or not playing then

                break
            end

            local actionTime =
                tonumber(
                    action.Time
                )
                or previousTime

            local delay =
                math.max(
                    0,
                    actionTime -
                    previousTime
                )

            if not preciseWait(
                delay,
                token
            ) then

                break
            end

            if token ~= playbackToken
                or not playing then

                break
            end

            local success
            local reason

            if action.Type
                == "PlaceTower" then

                _, reason =
                    replayPlace(
                        action,
                        token
                    )

                success =
                    reason ~= "Cancelled"
                    and
                    reason ~= "Desync"
                    and
                    reason ~= "RemoteError"

            elseif action.Type
                == "UpgradeTower" then

                success, reason =
                    replayUpgrade(
                        action,
                        token
                    )

            elseif action.Type
                == "SellTower" then

                success, reason =
                    replaySell(
                        action,
                        token
                    )

            elseif action.Type
                == "MoveTower" then

                success, reason =
                    replayMove(
                        action,
                        token
                    )

            else

                warn(
                    "[MACRO] Unknown action:",
                    action.Type
                )

                success = false
                reason = "UnknownAction"
            end

            if token ~= playbackToken
                or not playing then

                break
            end

            if not success then

                warn(
                    "[MACRO] Action #",
                    index,
                    "failed:",
                    reason
                )

                -- Do not silently continue through a hard
                -- desync. Stop replay cleanly so later actions
                -- do not operate on incorrect towers.

                if reason == "Desync"
                    or reason == "IdentityMismatch"
                    or reason == "RemoteError" then

                    playing = false

                    status.Text =
                        "DESYNC #" ..
                        tostring(index)

                    break
                end
            end

            previousTime =
                actionTime
        end

        if token == playbackToken then

            playing = false
            replayTowers = {}

            if status.Text == "PLAYING" then
                status.Text = "READY"
            end
        end
    end)
end

--========================================================
-- STOP PLAY
--========================================================

local function stopReplay()

    playbackToken += 1

    playing = false

    replayTowers = {}

    status.Text =
        "REPLAY STOPPED"
end

--========================================================
-- RESET RUNTIME STATE
--========================================================

local function resetRuntimeState()

    recordingToken += 1
    playbackToken += 1

    recording = false
    playing = false

    knownTowers = nil
    towerRecords = {}

    macroTowerIds = {}
    replayTowers = {}

    nextTowerId = 0
    recordStart = 0
end

--========================================================
-- START RECORD
--========================================================

local function startRecording()

    if recording then
        return
    end

    if playing then
        stopReplay()
    end

    recordingToken += 1

    macro = {

        Name =
            "MyMacro",

        CreatedAt =
            os.time(),

        Actions = {}
    }

    towerRecords = {}
    macroTowerIds = {}
    replayTowers = {}

    nextTowerId = 0

    recordStart =
        os.clock()

    -- Snapshot pre-existing towers AFTER their attributes
    -- have had a chance to populate.
    --
    -- These are not recorded as new placements.

    towerRecords =
        snapshotTowers()

    recording = true

    status.TextColor3 =
        Color3.new(1, 1, 1)

    status.Text =
        "RECORDING"

    print(
        "[MACRO] Recording started"
    )
end

--========================================================
-- STOP RECORD
--========================================================

local function stopRecording()

    if not recording then
        return
    end

    -- Process one final state before switching recording off.

    processChanges()

    recording = false

    status.Text =
        "READY"

    local success, json =
        pcall(function()

            return HttpService:JSONEncode(
                macro
            )

        end)

    if not success then

        warn(
            "[MACRO] JSON encode failed:",
            json
        )

        return
    end

    print(
        "========== MACRO JSON =========="
    )

    print(json)

    print(
        "================================"
    )
end

--========================================================
-- CLEAR
--========================================================

local function clearMacro()

    stopReplay()

    recordingToken += 1

    recording = false

    macro = {

        Name =
            "MyMacro",

        CreatedAt =
            os.time(),

        Actions = {}
    }

    towerRecords = {}
    macroTowerIds = {}
    replayTowers = {}

    nextTowerId = 0
    recordStart = 0

    jsonBox.Text =
        ""

    status.Text =
        "CLEARED"
end

