--========================================================
-- JSON VALIDATION HELPERS
--========================================================

local function isFiniteNumber(value)

    if type(value) ~= "number" then
        return false
    end

    return value == value
        and value ~= math.huge
        and value ~= -math.huge
end

local function validateCFrameData(data)

    if type(data) ~= "table" then
        return false
    end

    if type(data.Components) == "table" then

        if #data.Components ~= 12 then
            return false
        end

        for i = 1, 12 do

            if not isFiniteNumber(
                tonumber(
                    data.Components[i]
                )
            ) then

                return false
            end
        end

        return true
    end

    if type(data.Position) ~= "table"
        or #data.Position < 3 then

        return false
    end

    for i = 1, 3 do

        if not isFiniteNumber(
            tonumber(
                data.Position[i]
            )
        ) then

            return false
        end
    end

    if data.LookVector ~= nil then

        if type(data.LookVector)
            ~= "table"
            or #data.LookVector < 3 then

            return false
        end

        for i = 1, 3 do

            if not isFiniteNumber(
                tonumber(
                    data.LookVector[i]
                )
            ) then

                return false
            end
        end
    end

    return true
end

local function validateAction(
    action,
    index
)

    if type(action) ~= "table" then

        return false,
            "Action #" ..
            tostring(index) ..
            " is not an object."
    end

    if type(action.Type)
        ~= "string" then

        return false,
            "Action #" ..
            tostring(index) ..
            " has no Type."
    end

    local validTypes = {

        PlaceTower = true,
        UpgradeTower = true,
        SellTower = true,
        MoveTower = true
    }

    if not validTypes[action.Type] then

        return false,
            "Action #" ..
            tostring(index) ..
            " has unknown Type: " ..
            tostring(action.Type)
    end

    if not isFiniteNumber(
        tonumber(action.Time)
    ) then

        return false,
            "Action #" ..
            tostring(index) ..
            " has invalid Time."
    end

    if tonumber(action.Time) < 0 then

        return false,
            "Action #" ..
            tostring(index) ..
            " has negative Time."
    end

    if type(action.TowerId)
        ~= "string"
        or action.TowerId == "" then

        return false,
            "Action #" ..
            tostring(index) ..
            " is missing TowerId."
    end

    if action.Type ~= "SellTower"
        and (
            action.UnitId == nil
            or tostring(
                action.UnitId
            ) == ""
        ) then

        return false,
            "Action #" ..
            tostring(index) ..
            " is missing UnitId."
    end

    if action.Type == "PlaceTower"
        or action.Type == "MoveTower"
        or action.Type == "UpgradeTower"
        or action.Type == "SellTower" then

        if not validateCFrameData(
            action.CFrame
        ) then

            return false,
                "Action #" ..
                tostring(index) ..
                " has invalid CFrame data."
        end
    end

    if action.Type == "UpgradeTower" then

        if action.LevelBefore == nil
            or action.LevelAfter == nil then

            return false,
                "Upgrade #" ..
                tostring(index) ..
                " is missing level information."
        end

        if tonumber(action.LevelBefore)
            == nil
            or tonumber(action.LevelAfter)
            == nil then

            return false,
                "Upgrade #" ..
                tostring(index) ..
                " has invalid levels."
        end

        if tonumber(action.LevelAfter)
            <= tonumber(action.LevelBefore) then

            return false,
                "Upgrade #" ..
                tostring(index) ..
                " does not increase the level."
        end
    end

    return true
end

--========================================================
-- LOAD JSON
--========================================================

local function loadJSON()

    if recording then
        stopRecording()
    end

    if playing then
        stopReplay()
    end

    local text =
        jsonBox.Text

    if not text
        or text:match("^%s*$") then

        status.Text =
            "JSON BOX EMPTY"

        return false
    end

    local success, decoded =
        pcall(function()

            return HttpService:JSONDecode(
                text
            )

        end)

    if not success then

        status.Text =
            "INVALID JSON"

        warn(
            "[MACRO] JSON decode error:",
            decoded
        )

        return false
    end

    if type(decoded) ~= "table" then

        status.Text =
            "INVALID MACRO"

        return false
    end

    if type(decoded.Actions)
        ~= "table" then

        status.Text =
            "NO ACTIONS FOUND"

        return false
    end

    if #decoded.Actions > 10000 then

        status.Text =
            "TOO MANY ACTIONS"

        warn(
            "[MACRO] Macro exceeds 10,000 actions."
        )

        return false
    end

    local previousTime = -math.huge

    for index, action in ipairs(
        decoded.Actions
    ) do

        local valid, reason =
            validateAction(
                action,
                index
            )

        if not valid then

            status.Text =
                "BAD JSON #" ..
                tostring(index)

            warn(
                "[MACRO]",
                reason
            )

            return false
        end

        local actionTime =
            tonumber(action.Time)

        if actionTime < previousTime then

            status.Text =
                "BAD TIMING #" ..
                tostring(index)

            warn(
                "[MACRO] Action times must be non-decreasing."
            )

            return false
        end

        previousTime =
            actionTime
    end

    --====================================================
    -- Only replace the current macro after ALL validation
    -- succeeds.
    --====================================================

    macro = {

        Name =
            type(decoded.Name) == "string"
            and decoded.Name
            or "ImportedMacro",

        CreatedAt =
            tonumber(decoded.CreatedAt)
            or os.time(),

        Actions =
            decoded.Actions
    }

    -- Reset every runtime state associated with the old
    -- recording/replay.

    recordingToken += 1
    playbackToken += 1

    recording = false
    playing = false

    towerRecords = {}
    macroTowerIds = {}
    replayTowers = {}

    nextTowerId = 0
    recordStart = 0

    status.Text =
        "LOADED "
        .. tostring(
            #macro.Actions
        )
        .. " ACTIONS"

    print(
        "[MACRO] JSON loaded:",
        macro.Name,
        #macro.Actions,
        "actions"
    )

    return true
end

