--========================================================
-- MINIMIZE
--========================================================

local function updateMinimize()

    if minimized then

        main.Size =
            UDim2.fromOffset(
                350,
                45
            )

        for _, child in ipairs(
            main:GetChildren()
        ) do

            if child ~= title
                and child ~= minimize
                and child ~= close then

                child.Visible = false
            end
        end

        minimize.Text = "+"
    else

        main.Size =
            UDim2.fromOffset(
                350,
                450
            )

        for _, child in ipairs(
            main:GetChildren()
        ) do

            child.Visible = true
        end

        minimize.Text = "—"
    end

    -- Ensure the title controls are always visible.

    title.Visible = true
    minimize.Visible = true
    close.Visible = true
end

addConnection(
    minimize.Activated:Connect(
        function()

            minimized =
                not minimized

            updateMinimize()
        end
    )
)

--========================================================
-- DRAGGING
--========================================================

local dragging = false
local dragStart = nil
local startPosition = nil

addConnection(
    title.InputBegan:Connect(
        function(input)

            if input.UserInputType
                == Enum.UserInputType.MouseButton1
                or input.UserInputType
                    == Enum.UserInputType.Touch then

                dragging = true

                dragStart =
                    input.Position

                startPosition =
                    main.Position
            end
        end
    )
)

addConnection(
    title.InputEnded:Connect(
        function(input)

            if input.UserInputType
                == Enum.UserInputType.MouseButton1
                or input.UserInputType
                    == Enum.UserInputType.Touch then

                dragging = false
            end
        end
    )
)

addConnection(
    UserInputService.InputChanged:Connect(
        function(input)

            if not dragging then
                return
            end

            if input.UserInputType
                == Enum.UserInputType.MouseMovement
                or input.UserInputType
                    == Enum.UserInputType.Touch then

                if not dragStart
                    or not startPosition then

                    return
                end

                local delta =
                    input.Position
                    -
                    dragStart

                main.Position =
                    UDim2.new(

                        startPosition.X.Scale,

                        startPosition.X.Offset
                            + delta.X,

                        startPosition.Y.Scale,

                        startPosition.Y.Offset
                            + delta.Y
                    )
            end
        end
    )
)

--========================================================
-- TOWER EVENT CONNECTIONS
--========================================================
--
-- These connections make recording responsive to changes
-- without depending entirely on a 0.15-second polling loop.
--
-- A small deferred process is used to allow attributes to
-- populate before the snapshot is evaluated.
--========================================================

local changeQueued = false

local function queueChangeProcessing()

    if not recording then
        return
    end

    if changeQueued then
        return
    end

    changeQueued = true

    task.defer(function()

        changeQueued = false

        if recording then
            processChanges()
        end
    end)
end

addConnection(
    TowersFolder.ChildAdded:Connect(
        function()
            queueChangeProcessing()
        end
    )
)

addConnection(
    TowersFolder.ChildRemoved:Connect(
        function()
            queueChangeProcessing()
        end
    )
)

--========================================================
-- ATTRIBUTE CHANGE TRACKING
--========================================================

-- Attribute signals are attached dynamically to tower
-- instances while recording.
--
-- The periodic scanner below only discovers newly-created
-- attribute-bearing instances; actual change processing is
-- deferred through the event system.

local towerAttributeConnections = {}

local function disconnectTowerAttributeConnections()

    for tower, list in pairs(
        towerAttributeConnections
    ) do

        for _, connection in ipairs(list) do

            pcall(function()
                connection:Disconnect()
            end)
        end

        towerAttributeConnections[tower] = nil
    end
end

local watchedAttributes = {

    "UnitId",
    "UnitID",
    "ModelName",
    "Level",
    "TowerLevel",
    "Upgrade",
    "UpgradeLevel",
    "TowerId",
    "UniqueId",
    "UniqueID",
    "UUID",
    "GUID",
    "Id",
    "ID",
    "InstanceId",
    "InstanceID",
    "OwnerUserId",
    "OwnerUserID",
    "Owner",
    "MacroTowerId",
    "MacroId"
}

local function watchTowerAttributes(tower)

    if towerAttributeConnections[tower] then
        return
    end

    local list = {}

    towerAttributeConnections[tower] =
        list

    for _, attributeName in ipairs(
        watchedAttributes
    ) do

        local connection =
            tower:GetAttributeChangedSignal(
                attributeName
            ):Connect(
                queueChangeProcessing
            )

        table.insert(
            list,
            connection
        )
    end
end

--========================================================
-- RECORDING SCANNER
--========================================================

task.spawn(function()

    while not shuttingDown
        and gui.Parent do

        if recording then

            for _, tower in ipairs(
                TowersFolder:GetChildren()
            ) do

                watchTowerAttributes(
                    tower
                )
            end

            processChanges()
        end

        -- This is only a safety/reconciliation scan.
        -- It is NOT the normal action detection mechanism.

        task.wait(0.05)
    end
end)

