            .. " | Cash: "
            .. tostring(
                getCash()
            )

        RunService.Heartbeat:Wait()
    end
end)

--========================================================
-- CLOSE
--========================================================

local function shutdown()

    if shuttingDown then
        return
    end

    shuttingDown = true

    -- Cancel replay/recording tasks.

    recordingToken += 1
    playbackToken += 1

    recording = false
    playing = false

    -- Stop all tower attribute listeners.

    disconnectTowerAttributeConnections()

    -- Stop all GUI/input listeners.

    disconnectAll()

    -- Clear runtime references.

    towerRecords = {}
    macroTowerIds = {}
    replayTowers = {}

    dragging = false

    -- Finally remove the GUI.

    if gui then

        pcall(function()
            gui:Destroy()
        end)

    end
end

addConnection(
    close.Activated:Connect(
        shutdown
    )
)

