--========================================================
-- STARTUP: LOAD EMBEDDED MACRO + AUTO PLAY
--========================================================
--
-- This is intentionally at the VERY END, after every
-- function used by loadJSON/playMacro has been defined.
--
-- It loads the macro embedded at the top of this script
-- (EMBEDDED_JSON) into the JSON box, validates it, and
-- starts playing it automatically.
--========================================================

task.spawn(function()

    task.wait(1)

    if shuttingDown then
        return
    end

    local embedded = EMBEDDED_JSON

    if type(embedded) ~= "string"
        or embedded:match("^%s*$") then

        status.Text =
            "EMBEDDED_JSON IS EMPTY"

        status.TextColor3 =
            Color3.fromRGB(255, 90, 90)

        return
    end

    --================================================
    -- Decode the embedded macro DIRECTLY.
    -- No TextBox, no clipboard, no files involved.
    --================================================

    local decodeOk, decoded =
        pcall(function()

            return HttpService:JSONDecode(
                embedded
            )

        end)

    if not decodeOk or type(decoded) ~= "table"
        or type(decoded.Actions) ~= "table" then

        status.Text =
            "EMBED JSON BROKEN"

        status.TextColor3 =
            Color3.fromRGB(255, 90, 90)

        warn(
            "[Tower Macro] Embedded JSON could not be decoded."
        )

        return
    end

    -- Show it in the JSON box for visibility only.
    -- Never fatal, even if the TextBox rejects big text.

    pcall(function()
        jsonBox.Text = embedded
    end)

    -- Run the SAME full validation path as the LOAD JSON
    -- button by temporarily loading from the box. If the
    -- TextBox lost content for any reason, fall back to
    -- loading the decoded table directly.

    local loadOk = loadJSON()

    if not loadOk and #decoded.Actions > 0 then

        warn(
            "[Tower Macro] TextBox path failed,",
            "loading decoded table directly."
        )

        macro = {

            Name =
                type(decoded.Name) == "string"
                and decoded.Name
                or "EmbeddedMacro",

            CreatedAt =
                tonumber(decoded.CreatedAt)
                or os.time(),

            Actions =
                decoded.Actions
        }

        recordingToken += 1
        playbackToken += 1
        recording = false
        playing = false
        towerRecords = {}
        macroTowerIds = {}
        replayTowers = {}
        nextTowerId = 0
        recordStart = 0

        loadOk = true
    end

    if not loadOk
        or #macro.Actions == 0 then

        -- loadJSON already set a specific error status.

        return
    end

    -- Proof, right on the title bar, that the embedded
    -- macro is loaded in this exact session.

    title.Text =
        "Tower Macro "
        .. MACRO_VERSION
        .. " | "
        .. tostring(#macro.Actions)
        .. " actions"

    status.Text =
        "MACRO LOADED"

    status.TextColor3 =
        Color3.fromRGB(90, 255, 130)

    print(
        "[Tower Macro] Embedded macro loaded:",
        #macro.Actions,
        "actions"
    )

    -- Give the game a moment after loading before replay.
    task.wait(1)

    if shuttingDown then
        return
    end

    print(
        "[Tower Macro] Auto-playing embedded macro..."
    )

    playMacro()
end)